const percentOf = (amount: number, percent: number): number =>
  (amount * percent) / 100;

const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const quotePremium = (items: unknown[]): number => {
  const basePremium = items.length * SWORD_BASE_PREMIUM;
  const withFirstInsuranceSurcharge =
    basePremium + percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
  return roundInMHPCOsFavour(withFirstInsuranceSurcharge + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({
    premium: quotePremium(step.items),
  })),
});
